import { randomUUID, createHash } from 'node:crypto';
import { pool, withTransaction } from './db.js';
import { config } from './config.js';
import { putArtifact } from './artifacts.js';
import { ApiError } from './service.js';
import { execFileSync } from 'node:child_process';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { assertAuditableCommits, assertIncrementalPaths, createWorktree, gitValue, initializePhaseRefs, mergeAndPushDetached, mergeWorkItem, reconcileIntegration, reconcileWorktree, removeWorktree } from './git-delivery.js';
import { nextAction, publicValue } from './projection.js';

const event=(c:any,p:string,t:string,correlation:string,payload:object)=>c.query(`INSERT INTO events(project_id,event_type,correlation_id,payload,actor_id) VALUES($1,$2,$3,$4,$5)`,[p,t,correlation,payload,config().operatorId]);
const key=(v:unknown)=>typeof v==='string'&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(v);
const idem=async(c:any,k:string)=>{const r=await c.query(`SELECT id FROM operations WHERE idempotency_key=$1`,[k]);return r.rows[0]?.id as string|undefined};
const operation=async(c:any,p:string,kind:string,k:string,correlation:string)=>{const id=randomUUID();await c.query(`INSERT INTO operations(id,project_id,kind,status,idempotency_key,correlation_id) VALUES($1,$2,$3,'SUCCEEDED',$4,$5)`,[id,p,kind,k,correlation]);return id};
const moduleTarget=async(c:any,state:string,trigger:string)=>{const q=await c.query(`SELECT wt.to_state FROM workflow_transitions wt JOIN workflow_definitions wd ON wd.id=wt.workflow_id WHERE wd.code='MODULE_DELIVERY' AND wd.version=1 AND wd.status='PUBLISHED' AND wt.from_state=$1 AND wt.trigger_code=$2`,[state,trigger]);if(!q.rowCount)throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');return q.rows[0].to_state as string};
const evidence=async(c:any,p:string,type:string,data:object,op:string)=>{const json=JSON.stringify({schema_version:1,...data});const a=await putArtifact(c,p,type,json,op);const md=await putArtifact(c,p,`${type}-markdown`,`# ${type}\n\n\`\`\`json\n${json}\n\`\`\`\n`,op);return{json:a,markdown:md};};
const paths=(value:unknown)=>Array.isArray(value)&&value.length>0&&value.every(path=>typeof path==='string'&&path.length<=512&&!path.startsWith('/')&&!path.includes('\\')&&!path.split('/').includes('..'));
const textList=(value:unknown)=>Array.isArray(value)&&value.length>0&&value.every(item=>typeof item==='string'&&item.trim().length>0);
const workItemContract=(item:any)=>{
  if(!item||typeof item!=='object'||typeof item.title!=='string'||!item.title.trim()||!textList(item.inputs)||!paths(item.allowlist)||!Array.isArray(item.denylist)||!item.denylist.every((path:unknown)=>typeof path==='string'&&path.length>0&&!path.startsWith('/')&&!path.includes('\\')&&!path.split('/').includes('..'))||typeof item.output!=='string'||!item.output.trim()||!textList(item.acceptance_criteria)||!Array.isArray(item.dependencies)||!Array.isArray(item.qa_matrix)||!item.qa_matrix.length||!item.qa_matrix.every((entry:any)=>entry&&typeof entry==='object'&&typeof entry.command==='string'&&entry.command.trim()&&typeof entry.cwd==='string'&&entry.cwd.trim()&&Number.isInteger(entry.timeout_seconds)&&entry.timeout_seconds>0&&textList(entry.acceptance_criteria))) throw new ApiError(422,'WORK_ITEM_CONTRACT_INVALID');
  const allow=new Set(item.allowlist), deny=new Set(item.denylist); if(allow.size!==item.allowlist.length||deny.size!==item.denylist.length||[...allow].some(path=>deny.has(path))) throw new ApiError(422,'WORK_ITEM_PATH_POLICY_INVALID');
};

export const materializeModule=async(projectId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const existing=await idem(c,idempotencyKey);if(existing)return{operation_id:existing,status:'ACCEPTED'};const moduleKey=body.module_key;if(!key(moduleKey))throw new ApiError(422,'MODULE_KEY_INVALID');const p=await c.query(`SELECT state FROM projects WHERE id=$1 FOR UPDATE`,[projectId]);if(!p.rowCount)throw new ApiError(404,'PROJECT_NOT_FOUND');if(p.rows[0].state!=='PRODUCT_COMMITMENT')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const rev=randomUUID(),moduleId=randomUUID(),round=randomUUID(),correlation=randomUUID(),op=await operation(c,projectId,'MATERIALIZE_MODULE',idempotencyKey,correlation);const payload={schema_version:1,module_key:moduleKey,name:body.name,objective:body.objective,scope:body.scope,out_of_scope:body.out_of_scope,dependencies:body.dependencies,acceptance_criteria:body.acceptance_criteria,source_gate:body.source_gate};await c.query(`INSERT INTO module_revisions(id,project_id,module_key,revision,payload,status) VALUES($1,$2,$3,1,$4,'PENDING_APPROVAL')`,[rev,projectId,moduleKey,payload]);await c.query(`INSERT INTO modules(id,project_id,module_key,current_revision_id) VALUES($1,$2,$3,$4)`,[moduleId,projectId,moduleKey,rev]);await c.query(`INSERT INTO module_rounds(id,module_id,revision_id,round_number,state) VALUES($1,$2,$3,1,'WAITING_FOR_MODULE_APPROVAL')`,[round,moduleId,rev]);const artifacts=await evidence(c,projectId,'module-definition',{...payload,module_id:moduleId,revision_id:rev,round_id:round,correlation_id:correlation},op);const gateId=randomUUID();await c.query(`INSERT INTO module_gates(id,project_id,module_id,revision_id,round_id,kind,evidence) VALUES($1,$2,$3,$4,$5,'MODULE_APPROVAL',$6)`,[gateId,projectId,moduleId,rev,round,{definition_hash:artifacts.json.hash}]);await event(c,projectId,'MODULE_MATERIALIZED',correlation,{module_id:moduleId,module_key:moduleKey,revision_id:rev,gate_id:gateId,evidence_hash:artifacts.json.hash});return{operation_id:op,status:'ACCEPTED',module_id:moduleId,revision_id:rev,gate_id:gateId};});

export const decideModule=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const existing=await idem(c,idempotencyKey);if(existing)return{operation_id:existing,status:'ACCEPTED'};const m=await c.query(`SELECT m.*,r.id revision_id FROM modules m JOIN module_revisions r ON r.id=m.current_revision_id WHERE m.id=$1 AND m.project_id=$2 FOR UPDATE`,[moduleId,projectId]);if(!m.rowCount)throw new ApiError(404,'MODULE_NOT_FOUND');const gate=(await c.query(`SELECT * FROM module_gates WHERE module_id=$1 AND revision_id=$2 AND kind='MODULE_APPROVAL' AND status='OPEN' FOR UPDATE`,[moduleId,m.rows[0].revision_id])).rows[0];if(!gate||Number(body.version)!==gate.version)throw new ApiError(409,'GATE_VERSION_CONFLICT');const approved=body.decision==='APPROVED',feedback=typeof body.feedback==='string'?body.feedback.trim():'';if(!approved&&!feedback)throw new ApiError(422,'GATE_FEEDBACK_REQUIRED');const correlation=randomUUID(),op=await operation(c,projectId,'DECIDE_MODULE',idempotencyKey,correlation);if(approved){const target=await moduleTarget(c,m.rows[0].state,'DECIDE_MODULE_APPROVED');await c.query(`UPDATE module_revisions SET status='APPROVED',approved_gate_id=$2 WHERE id=$1`,[m.rows[0].revision_id,gate.id]);await c.query(`UPDATE modules SET state=$2,version=version+1 WHERE id=$1`,[moduleId,target]);await c.query(`UPDATE module_rounds SET state=$2 WHERE id=$1`,[gate.round_id,target]);}await c.query(`UPDATE module_gates SET status=$2,decision=$3,feedback=$4,decided_at=clock_timestamp() WHERE id=$1`,[gate.id,approved?'APPROVED':'REJECTED',body.decision,feedback]);await event(c,projectId,approved?'MODULE_APPROVED':'MODULE_REJECTED',correlation,{module_id:moduleId,gate_id:gate.id,feedback});return{operation_id:op,status:'ACCEPTED'};});

export const completeDefinition=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const old=await idem(c,idempotencyKey);if(old)return{operation_id:old,status:'ACCEPTED'};const m=(await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0];if(!m)throw new ApiError(404,'MODULE_NOT_FOUND');const target=await moduleTarget(c,m.state,'DEFINITION_COMPLETED'),round=(await c.query(`SELECT * FROM module_rounds WHERE module_id=$1 ORDER BY round_number DESC LIMIT 1 FOR UPDATE`,[moduleId])).rows[0],correlation=randomUUID(),op=await operation(c,projectId,'COMPLETE_MODULE_DEFINITION',idempotencyKey,correlation);const artifacts=await evidence(c,projectId,'module-definition',{module_id:moduleId,revision_id:m.current_revision_id,round_id:round.id,...body,correlation_id:correlation},op),gateId=randomUUID();await c.query(`INSERT INTO module_gates(id,project_id,module_id,revision_id,round_id,kind,evidence) VALUES($1,$2,$3,$4,$5,'ARCHITECTURE_DECISION',$6)`,[gateId,projectId,moduleId,m.current_revision_id,round.id,{artifact_hash:artifacts.json.hash}]);await c.query(`UPDATE module_rounds SET state=$2 WHERE id=$1`,[round.id,target]);await c.query(`UPDATE modules SET state=$2,version=version+1 WHERE id=$1`,[moduleId,target]);await event(c,projectId,'MODULE_DEFINITION_COMPLETED',correlation,{module_id:moduleId,gate_id:gateId,evidence_hash:artifacts.json.hash});return{operation_id:op,status:'ACCEPTED',gate_id:gateId};});
export const decideArchitecture=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const m=(await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0];if(!m)throw new ApiError(404,'MODULE_NOT_FOUND');const gate=(await c.query(`SELECT * FROM module_gates WHERE module_id=$1 AND kind='ARCHITECTURE_DECISION' AND status='OPEN' FOR UPDATE`,[moduleId])).rows[0];if(!gate||Number(body.version)!==gate.version)throw new ApiError(409,'GATE_VERSION_CONFLICT');const approved=body.decision==='APPROVED',feedback=typeof body.feedback==='string'?body.feedback.trim():'';if(!approved&&!feedback)throw new ApiError(422,'GATE_FEEDBACK_REQUIRED');const correlation=randomUUID(),op=await operation(c,projectId,'DECIDE_ARCHITECTURE',idempotencyKey,correlation);if(approved){const target=await moduleTarget(c,m.state,'DECIDE_ARCHITECTURE');const artifacts=await evidence(c,projectId,'module-architecture',{module_id:moduleId,revision_id:m.current_revision_id,round_id:gate.round_id,decision:body.decision,alternatives:body.alternatives??[],consequences:body.consequences??[],risks:body.risks??[],correlation_id:correlation},op);await c.query(`UPDATE modules SET state=$2,version=version+1 WHERE id=$1`,[moduleId,target]);await c.query(`UPDATE module_rounds SET state=$2 WHERE id=$1`,[gate.round_id,target]);await c.query(`UPDATE module_gates SET status='APPROVED',decision=$2,feedback=$3,decided_at=clock_timestamp(),evidence=evidence||$4 WHERE id=$1`,[gate.id,body.decision,feedback,{architecture_hash:artifacts.json.hash}]);}else await c.query(`UPDATE module_gates SET status='REJECTED',decision=$2,feedback=$3,decided_at=clock_timestamp() WHERE id=$1`,[gate.id,body.decision,feedback]);await event(c,projectId,approved?'ARCHITECTURE_APPROVED':'ARCHITECTURE_REJECTED',correlation,{module_id:moduleId,gate_id:gate.id});return{operation_id:op,status:'ACCEPTED'};});
export const approveModulePlan=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const m=(await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0];if(!m)throw new ApiError(404,'MODULE_NOT_FOUND');const round=(await c.query(`SELECT * FROM module_rounds WHERE module_id=$1 ORDER BY round_number DESC LIMIT 1 FOR UPDATE`,[moduleId])).rows[0];if(m.state!=='PLANNING_IN_PROGRESS'||!Array.isArray(body.work_items)||!body.work_items.length)throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');for(const item of body.work_items)workItemContract(item);const correlation=randomUUID(),op=await operation(c,projectId,'APPROVE_MODULE_REVISION_PLAN',idempotencyKey,correlation),artifact=await evidence(c,projectId,'module-plan',{module_id:moduleId,revision_id:m.current_revision_id,round_id:round.id,work_items:body.work_items,correlation_id:correlation},op),ids:string[]=[];for(const item of body.work_items){const id=randomUUID();ids.push(id);await c.query(`INSERT INTO work_items(id,project_id,module_id,revision_id,round_id,title,payload) VALUES($1,$2,$3,$4,$5,$6,$7)`,[id,projectId,moduleId,m.current_revision_id,round.id,item.title.trim(),{schema_version:1,...item,plan_artifact_hash:artifact.json.hash,authorized_by:config().operatorId,authorized_at:new Date().toISOString()}]);}await c.query(`UPDATE module_rounds SET state='WORK_ITEMS_ACTIVE',completed_at=clock_timestamp() WHERE id=$1`,[round.id]);await c.query(`UPDATE modules SET state='WORK_ITEMS_ACTIVE',version=version+1 WHERE id=$1`,[moduleId]);await event(c,projectId,'MODULE_PLAN_APPROVED',correlation,{module_id:moduleId,work_item_ids:ids,evidence_hash:artifact.json.hash});return{operation_id:op,status:'ACCEPTED',work_item_ids:ids,evidence_hash:artifact.json.hash};});
export const startModuleRevision=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const m=(await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0];if(!m)throw new ApiError(404,'MODULE_NOT_FOUND');const previous=m.current_revision_id,old=(await c.query(`SELECT * FROM module_revisions WHERE id=$1 FOR UPDATE`,[previous])).rows[0],payload={...old.payload,...body,supersedes_revision_id:previous};const revision=randomUUID(),round=randomUUID(),correlation=randomUUID(),op=await operation(c,projectId,'START_MODULE_REVISION',idempotencyKey,correlation);await c.query(`UPDATE module_revisions SET status='SUPERSEDED' WHERE id=$1`,[previous]);await c.query(`UPDATE work_items SET state='SUPERSEDED',version=version+1 WHERE revision_id=$1 AND state NOT IN ('MERGED_TO_PHASE')`,[previous]);await c.query(`UPDATE module_gates SET status='CANCELLED',decided_at=clock_timestamp() WHERE revision_id=$1 AND status='OPEN'`,[previous]);await c.query(`INSERT INTO module_revisions(id,project_id,module_key,revision,payload,status) VALUES($1,$2,$3,$4,$5,'PENDING_APPROVAL')`,[revision,projectId,m.module_key,Number(old.revision)+1,payload]);await c.query(`INSERT INTO module_rounds(id,module_id,revision_id,round_number,state) SELECT $1,$2,$3,coalesce(max(round_number),0)+1,'DEFINITION_IN_PROGRESS' FROM module_rounds WHERE module_id=$2`,[round,moduleId,revision]);await c.query(`UPDATE modules SET current_revision_id=$2,state='DEFINITION_IN_PROGRESS',version=version+1 WHERE id=$1`,[moduleId,revision]);await event(c,projectId,'MODULE_REVISION_STARTED',correlation,{module_id:moduleId,revision_id:revision,supersedes_revision_id:previous});return{operation_id:op,status:'ACCEPTED',revision_id:revision};});

export const authorizeWorkItem=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const existing=await idem(c,idempotencyKey);if(existing)return{operation_id:existing,status:'ACCEPTED'};const m=await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId]);if(!m.rowCount)throw new ApiError(404,'MODULE_NOT_FOUND');workItemContract(body);const round=(await c.query(`SELECT id FROM module_rounds WHERE module_id=$1 ORDER BY round_number DESC LIMIT 1`,[moduleId])).rows[0];const id=randomUUID(),correlation=randomUUID(),op=await operation(c,projectId,'AUTHORIZE_WORK_ITEM',idempotencyKey,correlation);const payload={schema_version:1,inputs:body.inputs,allowlist:body.allowlist,denylist:body.denylist,output:body.output,acceptance_criteria:body.acceptance_criteria,dependencies:body.dependencies,qa_matrix:body.qa_matrix,authorized_by:config().operatorId,authorized_at:new Date().toISOString()};const artifact=await evidence(c,projectId,'module-plan',{work_item_id:id,...payload,correlation_id:correlation},op);await c.query(`INSERT INTO work_items(id,project_id,module_id,revision_id,round_id,title,payload) VALUES($1,$2,$3,$4,$5,$6,$7)`,[id,projectId,moduleId,m.rows[0].current_revision_id,round.id,(body.title as string).trim(),{...payload,plan_artifact_hash:artifact.json.hash}]);await c.query(`UPDATE modules SET state='WORK_ITEMS_ACTIVE',version=version+1 WHERE id=$1`,[moduleId]);await event(c,projectId,'WORK_ITEM_AUTHORIZED',correlation,{work_item_id:id,module_id:moduleId,evidence_hash:artifact.json.hash});return{operation_id:op,status:'ACCEPTED',work_item_id:id,evidence_hash:artifact.json.hash};});

export const phase3Detail=async(projectId:string)=>{
  const [modules,workItems,deliveries,findings,candidates,gates,jobs,artifacts]=await Promise.all([
    pool.query(`SELECT m.id,m.module_key,m.state,m.version,m.created_at,extract(epoch FROM clock_timestamp()-m.created_at)::integer AS duration_seconds,r.revision,r.payload->>'name' AS name,r.payload->>'objective' AS objective,r.payload->'scope' AS scope,r.payload->'out_of_scope' AS out_of_scope,r.payload->'dependencies' AS dependencies,r.payload->'acceptance_criteria' AS acceptance_criteria FROM modules m JOIN module_revisions r ON r.id=m.current_revision_id WHERE m.project_id=$1 ORDER BY m.created_at`,[projectId]),
    pool.query(`SELECT id,module_id,title,state,version,rework_rounds,created_at,extract(epoch FROM clock_timestamp()-created_at)::integer AS duration_seconds FROM work_items WHERE project_id=$1 ORDER BY created_at`,[projectId]),
    pool.query(`SELECT id,work_item_id,base_sha,head_sha,phase_before_sha,phase_head_sha,state,created_at,extract(epoch FROM clock_timestamp()-created_at)::integer AS duration_seconds,validations FROM deliveries WHERE project_id=$1 ORDER BY created_at DESC`,[projectId]),
    pool.query(`SELECT id,delivery_id,candidate_id,origin,severity,state,rule_code,description,created_at FROM findings WHERE project_id=$1 ORDER BY created_at DESC`,[projectId]),
    pool.query(`SELECT id,phase_sha,state,blocked_kind,version,created_at,extract(epoch FROM clock_timestamp()-created_at)::integer AS duration_seconds FROM integration_candidates WHERE project_id=$1 ORDER BY created_at DESC`,[projectId]),
    pool.query(`SELECT id,module_id,kind,version,status,decision,feedback,opened_at,decided_at,evidence FROM module_gates WHERE project_id=$1 ORDER BY opened_at DESC`,[projectId]),
    pool.query(`SELECT kind,status,heartbeat_at,lease_expires_at,available_at AS created_at FROM jobs WHERE project_id=$1 AND kind='DEVELOP_WORK_ITEM' ORDER BY available_at DESC`,[projectId]),
    pool.query(`SELECT artifact_type,sha256,created_at FROM artifacts WHERE project_id=$1 ORDER BY created_at DESC`,[projectId])
  ]);
  const expose=(rows:any[])=>rows.map(row=>publicValue({...row,...(typeof row.state==='string'?{next_action:nextAction(row.state,row.blocked_kind)}:{})}));
  return {modules:expose(modules.rows),work_items:expose(workItems.rows),deliveries:expose(deliveries.rows),findings:expose(findings.rows),candidates:expose(candidates.rows),gates:expose(gates.rows),jobs:expose(jobs.rows),evidence:artifacts.rows};
};

export const findingFingerprint=(description:string)=>createHash('sha256').update(description.trim().toLowerCase()).digest('hex');

const legacyStartDevelopment=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{throw new ApiError(410,'PHASE3_LEGACY_COMMAND_DISABLED');});

const legacySubmitQa=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{throw new ApiError(410,'PHASE3_LEGACY_COMMAND_DISABLED');});

const legacyCreateCandidate=async(projectId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{throw new ApiError(410,'PHASE3_LEGACY_COMMAND_DISABLED');});
const reworkInput=(body:Record<string,unknown>)=>{
  const findingIds=Array.isArray(body.finding_ids)?body.finding_ids:[];
  if(!findingIds.length||!findingIds.every(id=>typeof id==='string')||typeof body.delivery_id!=='string'||typeof body.head_sha!=='string'||typeof body.justification!=='string'||!body.justification.trim()) throw new ApiError(422,'REWORK_REFERENCE_REQUIRED');
  return {findingIds,deliveryId:body.delivery_id,headSha:body.head_sha,justification:body.justification.trim().slice(0,2000)};
};
export const authorizeRework=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const w=(await c.query(`SELECT * FROM work_items WHERE id=$1 AND project_id=$2 FOR UPDATE`,[workItemId,projectId])).rows[0];if(!w)throw new ApiError(404,'WORK_ITEM_NOT_FOUND');if(w.state!=='REWORK_ELIGIBLE')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const input=reworkInput(body),delivery=(await c.query(`SELECT id,head_sha FROM deliveries WHERE id=$1 AND project_id=$2 AND work_item_id=$3 FOR UPDATE`,[input.deliveryId,projectId,workItemId])).rows[0];if(!delivery||delivery.head_sha!==input.headSha)throw new ApiError(409,'REWORK_DELIVERY_SHA_NOT_PERTINENT');const findings=(await c.query(`SELECT f.id,f.severity FROM findings f JOIN finding_work_items fw ON fw.finding_id=f.id WHERE f.project_id=$1 AND fw.work_item_id=$2 AND f.id=ANY($3::uuid[]) AND f.state='OPEN' FOR UPDATE`,[projectId,workItemId,input.findingIds])).rows;if(findings.length!==input.findingIds.length)throw new ApiError(409,'REWORK_FINDING_NOT_PERTINENT');const correlation=randomUUID(),round=Number(w.rework_rounds)+1,critical=findings.some((x:any)=>x.severity==='CRITICAL'),reason=critical?'CRITICAL_FINDING':round>=3?'REWORK_LIMIT':body.repeated_finding===true?'REPEATED_FINDING':typeof body.scope_change==='string'?'SCOPE_CHANGE':typeof body.architecture_change==='string'?'ARCHITECTURE_CHANGE':null,op=await operation(c,projectId,reason?'ESCALATE_REWORK':'AUTHORIZE_REWORK',idempotencyKey,correlation),decisionId=randomUUID();await c.query(`INSERT INTO rework_decisions(id,project_id,work_item_id,revision_id,delivery_id,head_sha,finding_ids,justification,rework_round,status) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9,$10)`,[decisionId,projectId,workItemId,w.revision_id,input.deliveryId,input.headSha,JSON.stringify(input.findingIds),input.justification,round,reason?'ESCALATED':'ACTIVE']);const record={decision_id:decisionId,work_item_id:workItemId,revision_id:w.revision_id,delivery_id:input.deliveryId,head_sha:input.headSha,finding_ids:input.findingIds,justification:input.justification,limit:2,round,reason,correlation_id:correlation};const artifact=await evidence(c,projectId,'rework-decision',record,op);if(reason){const gateId=randomUUID();await c.query(`INSERT INTO rework_gates(id,project_id,work_item_id,revision_id,decision_id,reason,evidence) VALUES($1,$2,$3,$4,$5,$6,$7)`,[gateId,projectId,workItemId,w.revision_id,decisionId,reason,{rework_decision_hash:artifact.json.hash}]);await c.query(`UPDATE work_items SET state='WAITING_FOR_ESCALATION',version=version+1 WHERE id=$1`,[workItemId]);await event(c,projectId,'REWORK_ESCALATED',correlation,{...record,gate_id:gateId});return{operation_id:op,status:'ACCEPTED',escalated:true,gate_id:gateId};}await c.query(`UPDATE work_items SET rework_rounds=$2,version=version+1 WHERE id=$1`,[workItemId,round]);await c.query(`UPDATE findings SET state='FIXED_PENDING_REVALIDATION' WHERE id=ANY($1::uuid[])`,[input.findingIds]);await event(c,projectId,'REWORK_AUTHORIZED',correlation,record);return{operation_id:op,status:'ACCEPTED',escalated:false,decision_id:decisionId};});

export const decideReworkGate=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const gate=(await c.query(`SELECT g.*,d.rework_round FROM rework_gates g JOIN rework_decisions d ON d.id=g.decision_id WHERE g.project_id=$1 AND g.work_item_id=$2 AND g.status='OPEN' FOR UPDATE`,[projectId,workItemId])).rows[0];if(!gate||Number(body.version)!==gate.version||typeof body.decision!=='string'||!['AUTHORIZE_REWORK','ACCEPT_RISK','CHANGE_SCOPE','CHANGE_ARCHITECTURE','CLOSE'].includes(body.decision))throw new ApiError(409,'GATE_VERSION_CONFLICT');const feedback=typeof body.feedback==='string'?body.feedback.trim():'';if(!feedback)throw new ApiError(422,'GATE_FEEDBACK_REQUIRED');const correlation=randomUUID(),op=await operation(c,projectId,'DECIDE_REWORK_GATE',idempotencyKey,correlation),allow=body.decision==='AUTHORIZE_REWORK';await c.query(`UPDATE rework_gates SET status='DECIDED',decision=$2,feedback=$3,decided_at=clock_timestamp() WHERE id=$1`,[gate.id,body.decision,feedback]);await c.query(`UPDATE rework_decisions SET status=$2,resolved_at=clock_timestamp() WHERE id=$1`,[gate.decision_id,allow?'ACTIVE':body.decision==='ACCEPT_RISK'?'RISK_ACCEPTED':'CLOSED']);if(allow){await c.query(`UPDATE work_items SET rework_rounds=$2,state='REWORK_ELIGIBLE',version=version+1 WHERE id=$1`,[workItemId,gate.rework_round]);await c.query(`UPDATE findings SET state='FIXED_PENDING_REVALIDATION' WHERE id=ANY(SELECT jsonb_array_elements_text(finding_ids)::uuid FROM rework_decisions WHERE id=$1)`,[gate.decision_id]);}await event(c,projectId,'REWORK_GATE_DECIDED',correlation,{work_item_id:workItemId,gate_id:gate.id,decision:body.decision,feedback});return{operation_id:op,status:'ACCEPTED'};});

const legacyMergeWorkItemToPhase=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{throw new ApiError(410,'PHASE3_LEGACY_COMMAND_DISABLED');});

const legacyValidateCandidate=async(projectId:string,candidateId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{throw new ApiError(410,'PHASE3_LEGACY_COMMAND_DISABLED');});

const legacyStartIntegration=async(projectId:string,candidateId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{throw new ApiError(410,'PHASE3_LEGACY_COMMAND_DISABLED');});

// Phase 3 commands derive every Git fact from the repository.  HTTP may request
// a command but can never supply a worktree, SHA, QA result or integration ref.
const projectRepository=async(projectId:string)=>{const r=await pool.query(`SELECT repository_path,initial_sha FROM projects WHERE id=$1`,[projectId]);if(!r.rowCount)throw new ApiError(404,'PROJECT_NOT_FOUND');return r.rows[0] as {repository_path:string;initial_sha:string};};
const qaMatrix=(payload:any)=>Array.isArray(payload?.qa_matrix)?payload.qa_matrix:[];
const sanitizeQaOutput=(value:unknown)=>String(value??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g,'').replace(/((?:token|password|secret|authorization)\s*[:=]\s*)\S+/gi,'$1[REDACTED]').slice(0,4000);
const qaSeverity=(entry:any)=>['CRITICAL','HIGH','MEDIUM','LOW'].includes(entry?.severity)?entry.severity:'HIGH';
const runMatrix=(cwd:string,matrix:any[])=>matrix.map((entry:any,index:number)=>{const started=Date.now(),timeout=Number(entry.timeout_seconds)*1000;try{const output=execFileSync('sh',['-lc',entry.command],{cwd:join(cwd,entry.cwd),timeout,encoding:'utf8',stdio:['ignore','pipe','pipe']});return{index,command:entry.command,cwd:entry.cwd,timeout_seconds:entry.timeout_seconds,acceptance_criteria:entry.acceptance_criteria,severity:qaSeverity(entry),passed:true,duration_ms:Date.now()-started,output:sanitizeQaOutput(output)};}catch(error:any){return{index,command:entry.command,cwd:entry.cwd,timeout_seconds:entry.timeout_seconds,acceptance_criteria:entry.acceptance_criteria,severity:qaSeverity(entry),passed:false,timed_out:error?.signal==='SIGTERM'||error?.code==='ETIMEDOUT',duration_ms:Date.now()-started,output:sanitizeQaOutput(`${error?.stdout??''}\n${error?.stderr??''}`)};}});
const qaFinding=async(c:any,projectId:string,scope:{deliveryId?:string;candidateId?:string},origin:'DELIVERY_QA'|'CANDIDATE_VALIDATION',result:any,workItemId?:string)=>{const description=`${origin==='DELIVERY_QA'?'Delivery':'Candidate'} QA matrix command failed: ${result.command}`,rule=`QA_MATRIX_${result.index}`,fingerprint=findingFingerprint(`${rule}:${result.command}:${result.cwd}:${result.acceptance_criteria?.join('|')??''}`),insert=await c.query(`INSERT INTO findings(id,project_id,delivery_id,candidate_id,origin,severity,rule_code,fingerprint,description) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT DO NOTHING RETURNING id`,[randomUUID(),projectId,scope.deliveryId??null,scope.candidateId??null,origin,result.severity,rule,fingerprint,description]);if(insert.rows[0]?.id&&workItemId)await c.query(`INSERT INTO finding_work_items(finding_id,work_item_id) VALUES($1,$2) ON CONFLICT DO NOTHING`,[insert.rows[0].id,workItemId]);};
const gitFailure=(error:unknown)=>{const code=(error as any)?.code;return new ApiError(409,typeof code==='string'&&code.startsWith('GIT_')?code:'GIT_DIVERGED');};

export const startDevelopment=async(projectId:string,workItemId:string,_body:Record<string,unknown>,idempotencyKey:string)=>{
  const prior=await idem(pool,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};
  const repository=await projectRepository(projectId);const w=(await pool.query(`SELECT * FROM work_items WHERE id=$1 AND project_id=$2`,[workItemId,projectId])).rows[0];
  if(!w)throw new ApiError(404,'WORK_ITEM_NOT_FOUND');if(!['WAITING_FOR_WORK_ITEM_AUTHORIZATION','REWORK_ELIGIBLE'].includes(w.state))throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');
  // The request records intent only.  Repository inspection, worktree creation
  // and any agent invocation are worker side effects and must be recoverable.
  const worktreeId=randomUUID(),deliveryId=randomUUID(),jobId=randomUUID(),branch=`work-items/${workItemId}`,worktree=join(repository.repository_path,'.naamive-worktrees',worktreeId),base=repository.initial_sha;
  const reserved=await withTransaction(async c=>{const old=await idem(c,idempotencyKey);if(old)return null;const correlation=randomUUID(),op=randomUUID(),matrix=qaMatrix(w.payload).map((entry:any)=>({...entry}));await c.query(`INSERT INTO operations(id,project_id,kind,status,idempotency_key,correlation_id) VALUES($1,$2,'START_DEVELOPMENT','QUEUED',$3,$4)`,[op,projectId,idempotencyKey,correlation]);await c.query(`INSERT INTO worktrees(id,project_id,work_item_id,path,branch,base_sha,lease_expires_at,state) VALUES($1,$2,$3,$4,$5,$6,clock_timestamp()+interval '10 minutes','RESERVED')`,[worktreeId,projectId,workItemId,worktree,branch,base]);await c.query(`INSERT INTO deliveries(id,project_id,work_item_id,revision_id,worktree_id,base_sha,qa_matrix) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)`,[deliveryId,projectId,workItemId,w.revision_id,worktreeId,base,JSON.stringify(matrix)]);await c.query(`INSERT INTO jobs(id,operation_id,project_id,revision_id,delivery_id,kind,idempotency_key) VALUES($1,$2,$3,NULL,$4,'DEVELOP_WORK_ITEM',$5)`,[jobId,op,projectId,deliveryId,`development:${deliveryId}`]);await c.query(`UPDATE deliveries SET job_id=$2 WHERE id=$1`,[deliveryId,jobId]);await event(c,projectId,'DEVELOPMENT_RESERVED',correlation,{work_item_id:workItemId,delivery_id:deliveryId,job_id:jobId,branch,base_sha:base,qa_matrix:matrix});return{op,correlation};});
  if(!reserved)return{operation_id:(await idem(pool,idempotencyKey))!,status:'ACCEPTED'};
  return{operation_id:reserved.op,status:'ACCEPTED',delivery_id:deliveryId};
};

/** Worker-only Git side effect for a leased development job. */
export const prepareDevelopmentJob=async(job:any)=>{
  const delivery=(await pool.query(`SELECT d.*,t.path,t.branch,t.base_sha,w.id work_item_id,w.state work_item_state,p.repository_path,p.initial_sha FROM deliveries d JOIN worktrees t ON t.id=d.worktree_id JOIN work_items w ON w.id=d.work_item_id JOIN projects p ON p.id=d.project_id WHERE d.id=$1`,[job.delivery_id])).rows[0];
  if(!delivery)throw new ApiError(409,'DELIVERY_NOT_FOUND');
  if(delivery.work_item_state!=='WAITING_FOR_WORK_ITEM_AUTHORIZATION'&&delivery.work_item_state!=='REWORK_ELIGIBLE') return;
  let base:string;
  try { base=initializePhaseRefs(delivery.repository_path,delivery.initial_sha).phaseSha; const released=await pool.query(`SELECT id,path FROM worktrees WHERE project_id=$1 AND state='RELEASED' ORDER BY created_at LIMIT 1`,[delivery.project_id]); if(released.rowCount){removeWorktree(delivery.repository_path,released.rows[0].path);await pool.query(`UPDATE worktrees SET state='REMOVED' WHERE id=$1`,[released.rows[0].id]);} mkdirSync(join(delivery.repository_path,'.naamive-worktrees'),{recursive:true}); createWorktree(delivery.repository_path,delivery.path,delivery.branch,base); }
  catch(error) { throw gitFailure(error); }
  await withTransaction(async c=>{const artifact=await evidence(c,delivery.project_id,'development-delivery',{delivery_id:delivery.id,work_item_id:delivery.work_item_id,branch:delivery.branch,worktree:delivery.path,base_sha:base,job_id:job.id},job.operation_id);await c.query(`UPDATE worktrees SET state='ACTIVE',base_sha=$2,lease_expires_at=clock_timestamp()+interval '10 minutes' WHERE id=$1`,[delivery.worktree_id,base]);await c.query(`UPDATE deliveries SET base_sha=$2 WHERE id=$1`,[delivery.id,base]);await c.query(`UPDATE work_items SET state='DEVELOPMENT_IN_PROGRESS',version=version+1 WHERE id=$1`,[delivery.work_item_id]);await event(c,delivery.project_id,'DEVELOPMENT_STARTED',job.operation_id,{work_item_id:delivery.work_item_id,delivery_id:delivery.id,job_id:job.id,branch:delivery.branch,base_sha:base,evidence_hash:artifact.json.hash});});
};

export const submitQa=async(projectId:string,workItemId:string,_body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const w=(await c.query(`SELECT * FROM work_items WHERE id=$1 AND project_id=$2 FOR UPDATE`,[workItemId,projectId])).rows[0];if(!w)throw new ApiError(404,'WORK_ITEM_NOT_FOUND');if(w.state!=='DEVELOPMENT_IN_PROGRESS')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const d=(await c.query(`SELECT d.*,t.path,t.branch FROM deliveries d JOIN worktrees t ON t.id=d.worktree_id WHERE d.work_item_id=$1 AND d.state='DEVELOPMENT_IN_PROGRESS' ORDER BY d.created_at DESC LIMIT 1 FOR UPDATE`,[workItemId])).rows[0];if(!d)throw new ApiError(409,'DELIVERY_NOT_FOUND');let head:string,changed:string[],commits:string[],results:any[];const matrix=qaMatrix({qa_matrix:d.qa_matrix}).map((entry:any)=>({...entry}));try{head=gitValue(d.path,'rev-parse','HEAD');commits=assertAuditableCommits(d.path,d.base_sha,workItemId,head);changed=assertIncrementalPaths(d.path,d.base_sha,w.payload.allowlist,w.payload.denylist);if(!changed.length)throw new ApiError(409,'GIT_DIVERGED');results=runMatrix(d.path,matrix);}catch(error){throw error instanceof ApiError?error:gitFailure(error);}const failed=results.filter(x=>!x.passed),correlation=randomUUID(),op=await operation(c,projectId,'SUBMIT_QA',idempotencyKey,correlation);await c.query(`UPDATE deliveries SET head_sha=$2,commits=$3::jsonb,validations=$4::jsonb,state='QA_IN_PROGRESS' WHERE id=$1`,[d.id,head,JSON.stringify(commits),JSON.stringify(results)]);for(const result of failed)await qaFinding(c,projectId,{deliveryId:d.id},'DELIVERY_QA',result,workItemId);const blocking=failed.length>0;await c.query(`UPDATE deliveries SET state=$2 WHERE id=$1`,[d.id,blocking?'QA_REJECTED':'QA_APPROVED']);if(blocking)await c.query(`UPDATE worktrees SET state='RELEASED' WHERE id=$1`,[d.worktree_id]);await c.query(`UPDATE work_items SET state=$2,version=version+1 WHERE id=$1`,[workItemId,blocking?'REWORK_ELIGIBLE':'READY_FOR_PHASE_MERGE']);await c.query(`UPDATE rework_decisions SET status='RESOLVED',resolved_at=clock_timestamp() WHERE work_item_id=$1 AND revision_id=$2 AND status='ACTIVE'`,[workItemId,w.revision_id]);if(!blocking)await c.query(`UPDATE findings SET state='CLOSED',revalidation_delivery_id=$2 WHERE state='FIXED_PENDING_REVALIDATION' AND delivery_id IN (SELECT id FROM deliveries WHERE work_item_id=$1 AND created_at < (SELECT created_at FROM deliveries WHERE id=$2))`,[workItemId,d.id]);await evidence(c,projectId,'qa-report',{delivery_id:d.id,work_item_id:workItemId,base_sha:d.base_sha,head_sha:head,commits,changed_paths:changed,matrix,results,correlation_id:correlation},op);await event(c,projectId,blocking?'QA_REJECTED':'QA_APPROVED',correlation,{work_item_id:workItemId,delivery_id:d.id,head_sha:head});return{operation_id:op,status:'ACCEPTED',approved:!blocking};});

export const mergeWorkItemToPhase=async(projectId:string,workItemId:string,_body:Record<string,unknown>,idempotencyKey:string)=>{const prior=await idem(pool,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const repository=await projectRepository(projectId);const row=(await pool.query(`SELECT w.*,d.head_sha,d.worktree_id FROM work_items w JOIN deliveries d ON d.work_item_id=w.id WHERE w.id=$1 AND w.project_id=$2 AND d.state='QA_APPROVED' ORDER BY d.created_at DESC LIMIT 1`,[workItemId,projectId])).rows[0];if(!row||row.state!=='READY_FOR_PHASE_MERGE')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');let phaseSha:string;try{phaseSha=mergeWorkItem(repository.repository_path,'phases/3',`work-items/${workItemId}`,row.head_sha);}catch(error){throw gitFailure(error);}return withTransaction(async c=>{const correlation=randomUUID(),op=await operation(c,projectId,'MERGE_WORK_ITEM_TO_PHASE',idempotencyKey,correlation);await c.query(`UPDATE worktrees SET state='RELEASED' WHERE id=$1`,[row.worktree_id]);await c.query(`UPDATE work_items SET state='MERGED_TO_PHASE',version=version+1 WHERE id=$1`,[workItemId]);await event(c,projectId,'WORK_ITEM_MERGED_TO_PHASE',correlation,{work_item_id:workItemId,phase_sha:phaseSha});return{operation_id:op,status:'ACCEPTED',phase_sha:phaseSha};});};

export const createCandidate=async(projectId:string,_body:Record<string,unknown>,idempotencyKey:string)=>{const prior=await idem(pool,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const repository=await projectRepository(projectId);let phaseSha:string;try{phaseSha=gitValue(repository.repository_path,'rev-parse','phases/3');}catch(error){throw gitFailure(error);}return withTransaction(async c=>{const rows=(await c.query(`SELECT w.id AS work_item_id,w.payload->'qa_matrix' AS qa_matrix,d.head_sha,d.commits FROM work_items w JOIN LATERAL (SELECT head_sha,commits FROM deliveries WHERE work_item_id=w.id AND state='QA_APPROVED' ORDER BY created_at DESC LIMIT 1) d ON true WHERE w.project_id=$1 AND w.state='MERGED_TO_PHASE' ORDER BY w.created_at`,[projectId])).rows;if(!rows.length)throw new ApiError(409,'INTEGRATION_CANDIDATE_EMPTY');const items=rows.map((item:any)=>({work_item_id:item.work_item_id,head_sha:item.head_sha,commits:item.commits,qa_matrix:qaMatrix(item)}));const correlation=randomUUID(),op=await operation(c,projectId,'CREATE_INTEGRATION_CANDIDATE',idempotencyKey,correlation),id=randomUUID(),manifest={phase_sha:phaseSha,work_items:items};await c.query(`INSERT INTO integration_candidates(id,project_id,phase_sha,manifest) VALUES($1,$2,$3,$4)`,[id,projectId,phaseSha,manifest]);await evidence(c,projectId,'integration-candidate-manifest',{candidate_id:id,manifest,correlation_id:correlation},op);await event(c,projectId,'INTEGRATION_CANDIDATE_CREATED',correlation,{candidate_id:id,phase_sha:phaseSha,manifest});return{operation_id:op,status:'ACCEPTED',candidate_id:id};});};

export const validateCandidate=async(projectId:string,candidateId:string,_body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const candidate=(await c.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2 FOR UPDATE`,[candidateId,projectId])).rows[0];if(!candidate||candidate.state!=='CANDIDATE_CREATED')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const repository=await projectRepository(projectId),entries=(candidate.manifest?.work_items??[]).flatMap((item:any)=>qaMatrix(item).map((entry:any)=>({...entry,work_item_id:item.work_item_id}))),matrix=entries.map(({work_item_id,...entry}:any)=>entry),temporary=join(repository.repository_path,'.naamive-candidates',candidateId);let results:any[];try{if(gitValue(repository.repository_path,'rev-parse',candidate.phase_sha)!==candidate.phase_sha)throw new ApiError(409,'GIT_DIVERGED');mkdirSync(join(repository.repository_path,'.naamive-candidates'),{recursive:true});execFileSync('git',['-C',repository.repository_path,'worktree','add','--detach',temporary,candidate.phase_sha]);results=runMatrix(temporary,matrix).map((result:any)=>({...result,work_item_id:entries[result.index].work_item_id}));}catch(error){throw error instanceof ApiError?error:gitFailure(error);}finally{try{execFileSync('git',['-C',repository.repository_path,'worktree','remove','--force',temporary]);}catch{}}const failed=results.filter(x=>!x.passed),correlation=randomUUID(),op=await operation(c,projectId,'VALIDATE_INTEGRATION_CANDIDATE',idempotencyKey,correlation);for(const result of failed)await qaFinding(c,projectId,{candidateId},'CANDIDATE_VALIDATION',result,result.work_item_id);await c.query(`UPDATE integration_candidates SET state=$2,blocked_kind=$3,version=version+1 WHERE id=$1`,[candidateId,failed.length?'INTEGRATION_BLOCKED':'INTEGRATION_PENDING',failed.length?'VALIDATION_CODE_DEFECT':null]);await evidence(c,projectId,'integration-candidate-validation',{candidate_id:candidateId,phase_sha:candidate.phase_sha,manifest:candidate.manifest,matrix:entries,results,correlation_id:correlation},op);await event(c,projectId,failed.length?'CANDIDATE_VALIDATION_FAILED':'CANDIDATE_VALIDATED',correlation,{candidate_id:candidateId,phase_sha:candidate.phase_sha});return{operation_id:op,status:'ACCEPTED',approved:!failed.length};});

export const startIntegration=async(projectId:string,candidateId:string,_body:Record<string,unknown>,idempotencyKey:string)=>{const prior=await idem(pool,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const repository=await projectRepository(projectId);let before:string;try{before=gitValue(repository.repository_path,'rev-parse','integration');}catch(error){throw gitFailure(error);}const reserved=await withTransaction(async c=>{const candidate=(await c.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2 FOR UPDATE`,[candidateId,projectId])).rows[0];if(!candidate||candidate.state!=='INTEGRATION_PENDING')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');if(gitValue(repository.repository_path,'rev-parse','phases/3')!==candidate.phase_sha)throw new ApiError(409,'GIT_DIVERGED');const correlation=randomUUID(),op=await operation(c,projectId,'START_INTEGRATION',idempotencyKey,correlation),attempt=randomUUID();await c.query(`INSERT INTO integration_attempts(id,project_id,candidate_id,idempotency_key,integration_before_sha,candidate_sha,state) VALUES($1,$2,$3,$4,$5,$6,'RESERVED')`,[attempt,projectId,candidateId,idempotencyKey,before,candidate.phase_sha]);await evidence(c,projectId,'integration-attempt-intent',{attempt_id:attempt,candidate_id:candidateId,integration_before_sha:before,candidate_sha:candidate.phase_sha,expected_parents:[before,candidate.phase_sha],operation:'merge-and-push-detached',correlation_id:correlation},op);await c.query(`UPDATE integration_candidates SET state='INTEGRATION_IN_PROGRESS',version=version+1 WHERE id=$1`,[candidateId]);await event(c,projectId,'INTEGRATION_ATTEMPT_RESERVED',correlation,{candidate_id:candidateId,attempt_id:attempt,integration_before_sha:before,candidate_sha:candidate.phase_sha});return{attempt,op,correlation,candidate};});let result:any;try{result=mergeAndPushDetached(repository.repository_path,'phases/3','integration',reserved.candidate.phase_sha,before);}catch(error){const code=(error as any)?.code??'GIT_DIVERGED',blocked=code==='GIT_DIVERGED'?'GIT_DIVERGED':'GIT_RECOVERABLE';await pool.query(`UPDATE integration_attempts SET state='FAILED' WHERE id=$1`,[reserved.attempt]);await pool.query(`UPDATE integration_candidates SET state='INTEGRATION_BLOCKED',blocked_kind=$2,version=version+1 WHERE id=$1`,[candidateId,blocked]);throw new ApiError(409,code);}return withTransaction(async c=>{await c.query(`UPDATE integration_attempts SET merge_sha=$2,push_sha=$2,state='INTEGRATED' WHERE id=$1`,[reserved.attempt,result.mergeSha]);await c.query(`UPDATE integration_candidates SET state='INTEGRATED',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);await evidence(c,projectId,'integration-attempt',{attempt_id:reserved.attempt,candidate_id:candidateId,integration_before_sha:before,candidate_sha:reserved.candidate.phase_sha,merge_sha:result.mergeSha,push_sha:result.mergeSha,parents:[before,reserved.candidate.phase_sha]},reserved.op);await event(c,projectId,'INTEGRATION_COMPLETED',reserved.correlation,{candidate_id:candidateId,attempt_id:reserved.attempt,merge_sha:result.mergeSha});return{operation_id:reserved.op,status:'ACCEPTED',attempt_id:reserved.attempt,merge_sha:result.mergeSha};});};

export const revalidateCandidate=async(projectId:string,candidateId:string,body:Record<string,unknown>,key:string)=>{await pool.query(`UPDATE integration_candidates SET state='CANDIDATE_CREATED',blocked_kind=NULL,version=version+1 WHERE id=$1 AND project_id=$2 AND state='INTEGRATION_BLOCKED' AND blocked_kind='VALIDATION_TRANSIENT'`,[candidateId,projectId]);return validateCandidate(projectId,candidateId,body,key);};
export const retryIntegration=async(projectId:string,candidateId:string,body:Record<string,unknown>,key:string)=>{const candidate=(await pool.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2`,[candidateId,projectId])).rows[0],attempt=(await pool.query(`SELECT * FROM integration_attempts WHERE candidate_id=$1 ORDER BY created_at DESC LIMIT 1`,[candidateId])).rows[0];if(!candidate||candidate.state!=='INTEGRATION_BLOCKED'||candidate.blocked_kind!=='GIT_RECOVERABLE'||!attempt)throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const repository=await projectRepository(projectId);let result:string;try{result=reconcileIntegration(repository.repository_path,'integration',attempt.integration_before_sha,attempt.candidate_sha);}catch(error){throw gitFailure(error);}if(result==='APPLIED_UNRECORDED'){await pool.query(`UPDATE integration_attempts SET state='INTEGRATED',merge_sha=coalesce(merge_sha,$2),push_sha=coalesce(push_sha,$2) WHERE id=$1`,[attempt.id,gitValue(repository.repository_path,'rev-parse','origin/integration')]);await pool.query(`UPDATE integration_candidates SET state='INTEGRATED',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);return{status:'ACCEPTED',result};}if(result==='DIVERGED'){await pool.query(`UPDATE integration_candidates SET blocked_kind='GIT_DIVERGED',version=version+1 WHERE id=$1`,[candidateId]);throw new ApiError(409,'GIT_DIVERGED');}await pool.query(`UPDATE integration_candidates SET state='INTEGRATION_PENDING',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);return startIntegration(projectId,candidateId,body,key);};
export const supersedeCandidate=async(projectId:string,candidateId:string,_body:Record<string,unknown>,key:string)=>withTransaction(async c=>{const old=await idem(c,key);if(old)return{operation_id:old,status:'ACCEPTED'};const candidate=(await c.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2 FOR UPDATE`,[candidateId,projectId])).rows[0];if(!candidate||candidate.state!=='INTEGRATION_BLOCKED'||candidate.blocked_kind!=='VALIDATION_CODE_DEFECT')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const responsible=await c.query(`SELECT DISTINCT work_item_id FROM finding_work_items WHERE finding_id IN (SELECT id FROM findings WHERE candidate_id=$1 AND state='OPEN')`,[candidateId]);if(!responsible.rowCount)throw new ApiError(409,'CANDIDATE_FINDING_RESPONSIBILITY_REQUIRED');const op=await operation(c,projectId,'SUPERSEDE_CANDIDATE',key,randomUUID());await c.query(`UPDATE integration_candidates SET state='SUPERSEDED',version=version+1 WHERE id=$1`,[candidateId]);await c.query(`UPDATE work_items SET state='REWORK_ELIGIBLE',version=version+1 WHERE id=ANY($1::uuid[])`,[responsible.rows.map((x:any)=>x.work_item_id)]);await c.query(`UPDATE modules SET state='WORK_ITEMS_ACTIVE',version=version+1 WHERE id IN (SELECT DISTINCT module_id FROM work_items WHERE id=ANY($1::uuid[]))`,[responsible.rows.map((x:any)=>x.work_item_id)]);await event(c,projectId,'MODULE_REOPENED_FOR_CANDIDATE_FINDING',randomUUID(),{candidate_id:candidateId,work_item_ids:responsible.rows.map((x:any)=>x.work_item_id)});await event(c,projectId,'CANDIDATE_SUPERSEDED',randomUUID(),{candidate_id:candidateId});return{operation_id:op,status:'ACCEPTED'};});
export const reconcileIntegrationAttempt=async(projectId:string,candidateId:string,_body:Record<string,unknown>,key:string)=>{const candidate=(await pool.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2`,[candidateId,projectId])).rows[0];if(!candidate)throw new ApiError(404,'CANDIDATE_NOT_FOUND');const repository=await projectRepository(projectId);const attempt=(await pool.query(`SELECT * FROM integration_attempts WHERE candidate_id=$1 ORDER BY created_at DESC LIMIT 1`,[candidateId])).rows[0];if(!attempt)throw new ApiError(409,'INTEGRATION_ATTEMPT_NOT_FOUND');let state:string;try{state=reconcileIntegration(repository.repository_path,'integration',attempt.integration_before_sha,candidate.phase_sha);}catch(error){throw gitFailure(error);}return withTransaction(async c=>{const op=await operation(c,projectId,'RECONCILE_INTEGRATION',key,randomUUID());if(state==='APPLIED_UNRECORDED')await c.query(`UPDATE integration_candidates SET state='INTEGRATED',version=version+1 WHERE id=$1`,[candidateId]);else if(state==='NOT_APPLIED')await c.query(`UPDATE integration_candidates SET state='INTEGRATION_PENDING',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);else await c.query(`UPDATE integration_candidates SET state='INTEGRATION_BLOCKED',blocked_kind='GIT_DIVERGED',version=version+1 WHERE id=$1`,[candidateId]);await event(c,projectId,'INTEGRATION_RECONCILED',randomUUID(),{candidate_id:candidateId,result:state});return{operation_id:op,status:'ACCEPTED',result:state};});};
export const archiveIntegration=async(projectId:string,candidateId:string,_body:Record<string,unknown>,key:string)=>{const candidate=(await pool.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2`,[candidateId,projectId])).rows[0];if(!candidate)throw new ApiError(404,'CANDIDATE_NOT_FOUND');const attempt=(await pool.query(`SELECT * FROM integration_attempts WHERE candidate_id=$1 ORDER BY created_at DESC LIMIT 1`,[candidateId])).rows[0];let remoteState='NO_ATTEMPT';if(attempt){const repository=await projectRepository(projectId);try{remoteState=reconcileIntegration(repository.repository_path,'integration',attempt.integration_before_sha,attempt.candidate_sha);}catch(error){throw gitFailure(error);}if(remoteState==='DIVERGED'){await pool.query(`UPDATE integration_candidates SET state='INTEGRATION_BLOCKED',blocked_kind='GIT_DIVERGED',version=version+1 WHERE id=$1`,[candidateId]);throw new ApiError(409,'ARCHIVE_RECONCILIATION_REQUIRED');}}return withTransaction(async c=>{const old=await idem(c,key);if(old)return{operation_id:old,status:'ACCEPTED'};const op=await operation(c,projectId,'ARCHIVE_INTEGRATION',key,randomUUID());if(remoteState==='APPLIED_UNRECORDED')await c.query(`UPDATE integration_attempts SET state='INTEGRATED' WHERE id=$1`,[attempt.id]);await c.query(`UPDATE integration_candidates SET state='ARCHIVED',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);await event(c,projectId,'INTEGRATION_ARCHIVED',randomUUID(),{candidate_id:candidateId,remote_reconciliation:remoteState});return{operation_id:op,status:'ACCEPTED'};});};

export const reconcileDevelopmentWorktree=async(projectId:string,workItemId:string,key:string)=>withTransaction(async c=>{const prior=await idem(c,key);if(prior)return{operation_id:prior,status:'ACCEPTED'};const tree=(await c.query(`SELECT t.* FROM worktrees t WHERE t.project_id=$1 AND t.work_item_id=$2 AND t.state IN ('ACTIVE','RESERVED') ORDER BY t.created_at DESC LIMIT 1 FOR UPDATE`,[projectId,workItemId])).rows[0];if(!tree)throw new ApiError(404,'WORKTREE_NOT_FOUND');const repository=await projectRepository(projectId);let result;try{result=reconcileWorktree(repository.repository_path,tree.path,tree.branch,tree.base_sha);}catch(error){throw gitFailure(error);}const op=await operation(c,projectId,'RECONCILE_WORKTREE',key,randomUUID());if(result==='ACTIVE')await c.query(`UPDATE worktrees SET lease_expires_at=clock_timestamp()+interval '10 minutes',state='ACTIVE' WHERE id=$1`,[tree.id]);else{await c.query(`UPDATE worktrees SET state='BLOCKED' WHERE id=$1`,[tree.id]);await c.query(`UPDATE work_items SET state='WAITING_FOR_ESCALATION',version=version+1 WHERE id=$1`,[workItemId]);}await event(c,projectId,'WORKTREE_RECONCILED',randomUUID(),{work_item_id:workItemId,worktree_id:tree.id,result});return{operation_id:op,status:'ACCEPTED',result};});
